<?php require 'config/database.php';require 'helpers/functions.php';admin_required();if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$n=trim($_POST['name']??'');$u=trim($_POST['username']??'');$p=$_POST['password']??'';$r=$_POST['role']??'staff';if($n===''||$u===''||strlen($p)<10||!in_array($r,['admin','staff'],true))msg('Data tidak valid; password minimal 10 karakter.','error');else{try{$s=$pdo->prepare('INSERT INTO users(name,username,password,role) VALUES(?,?,?,?)');$s->execute([$n,$u,password_hash($p,PASSWORD_DEFAULT),$r]);msg('Pengguna dibuat.');}catch(PDOException $e){msg('Username sudah digunakan.','error');}}go('users.php');}$rows=$pdo->query('SELECT name,username,role,created_at FROM users ORDER BY id DESC')->fetchAll();header_html('Manajemen Pengguna');echo '<section><form method="post" class="grid"><input type="hidden" name="csrf" value="'.e(token()).'"><div><label>Nama</label><input name="name" required></div><div><label>Username</label><input name="username" required></div><div><label>Password minimal 10 karakter</label><input type="password" name="password" minlength="10" required></div><div><label>Peran</label><select name="role"><option value="staff">Staff</option><option value="admin">Admin</option></select></div><button>Tambah Pengguna</button></form></section><section><table><tr><th>Nama</th><th>Username</th><th>Peran</th><th>Dibuat</th></tr>';foreach($rows as $r)echo '<tr><td>'.e($r['name']).'</td><td>'.e($r['username']).'</td><td>'.e($r['role']).'</td><td>'.e($r['created_at']).'</td></tr>';echo '</table></section>';footer_html();